<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){exit("Somente CLI.\n");}$root=dirname(__DIR__);require_once $root.'/config/nexa_env.php';require $root.'/config/pdo.php';require_once $root.'/config/fiscal_module.php';fiscal_ensure_aux_schema($pdo);
$tables=['fiscal_ncms','fiscal_cests','fiscal_ibs_cbs_classifications','fiscal_cbs_rates','fiscal_ibs_uf_rates','fiscal_ibs_mun_rates','fiscal_cities','fiscal_states'];
echo "NEXA FISCAL V2.6 - AUDITORIA DOS CATÁLOGOS\n";foreach($tables as $t){if(!fiscal_table_exists($pdo,$t))continue;$g=(int)$pdo->query("SELECT COUNT(*) FROM `{$t}` WHERE company_id=0 AND is_active=1")->fetchColumn();$l=(int)$pdo->query("SELECT COUNT(*) FROM `{$t}` WHERE company_id<>0 AND is_active=1")->fetchColumn();printf("%-38s global=%-7d local_ativo=%d\n",$t,$g,$l);}echo "\nIBPT global por UF:\n";foreach($pdo->query("SELECT uf,version,COUNT(*) qtd,MIN(validity_start) inicio,MAX(validity_end) fim FROM fiscal_ibpt_rates WHERE is_active=1 GROUP BY uf,version ORDER BY uf,version DESC")->fetchAll(PDO::FETCH_ASSOC)?:[] as $r)echo implode(' | ',$r)."\n";
echo "\nProdutos com referências ausentes no catálogo global:\n";$sql="SELECT p.company_id,p.product_id,p.ncm,p.cest,p.ibs_cbs_classification_code FROM fiscal_product_tax p LEFT JOIN fiscal_ncms n ON n.company_id=0 AND n.ncm=p.ncm AND n.is_active=1 LEFT JOIN fiscal_cests c ON c.company_id=0 AND c.cest=p.cest AND c.ncm=p.ncm AND c.is_active=1 LEFT JOIN fiscal_ibs_cbs_classifications i ON i.company_id=0 AND i.classification_code=p.ibs_cbs_classification_code AND i.is_active=1 WHERE (COALESCE(p.ncm,'')<>'' AND n.id IS NULL) OR (COALESCE(p.cest,'')<>'' AND c.id IS NULL) OR (COALESCE(p.ibs_cbs_classification_code,'')<>'' AND i.id IS NULL) ORDER BY p.company_id,p.product_id LIMIT 200";foreach($pdo->query($sql)->fetchAll(PDO::FETCH_ASSOC)?:[] as $r)echo json_encode($r,JSON_UNESCAPED_UNICODE)."\n";echo "[OK] Auditoria concluída.\n";
